function configureAdvancedType(trigger,column,type){const submenu=document.getElementById("typeSubmenu");if(!submenu)return;submenu.classList.remove("status-menu");if(type==="text"){const colors=["#37352f","#d44c47","#cb912f","#448361","#2383e2","#9065b0","#999894"];submenu.innerHTML=`<div class="type-submenu-title">Formato de texto</div><button data-text-style="normal"><span>Ag</span><span>Normal</span></button><button data-text-style="italic"><span class="italic">Ag</span><span>Cursiva</span></button><button data-text-style="bold"><strong>Ag</strong><span>Negrita</span></button><div class="type-submenu-title">Color del texto</div><div class="color-options">${colors.map(color=>`<button data-text-color="${color}" style="background:${color}"></button>`).join("")}</div><div class="type-submenu-title">Color de fondo</div><div class="color-options">${colors.map(color=>`<button data-cell-color="${color}" style="background:${color}"></button>`).join("")}</div>`;submenu.querySelectorAll("[data-text-style]").forEach(button=>button.addEventListener("click",()=>{column.textStyle=button.dataset.textStyle;save();renderTable();submenu.classList.remove("open")}));submenu.querySelectorAll("[data-text-color]").forEach(button=>button.addEventListener("click",()=>{column.textColor=button.dataset.textColor;save();renderTable()}));submenu.querySelectorAll("[data-cell-color]").forEach(button=>button.addEventListener("click",()=>{column.cellColor=button.dataset.cellColor;save();renderTable()}))}else if(type==="date"){submenu.innerHTML=`<div class="type-submenu-title">Formato de fecha</div>${[["dd/mm/yyyy","30/12/2000"],["yyyy/mm/dd","2000/12/30"],["dd-mmm-yyyy","30-ene-2000"]].map(([value,label])=>`<button data-date-format="${value}"><span>${column.dateFormat===value?"✓":""}</span><span>${label}</span></button>`).join("")}`;submenu.querySelectorAll("[data-date-format]").forEach(button=>button.addEventListener("click",()=>{column.dateFormat=button.dataset.dateFormat;save();renderTable();submenu.classList.remove("open")}))}else if(type==="formula"){const company=activeCompany();const available=company.columns.filter(item=>item.id!==column.id&&["number","currency","percent","subtotal","total","formula"].includes(item.type));submenu.innerHTML=`<div class="type-submenu-title">Configurar fórmula</div><div class="formula-config"><label>Acción</label><select class="talent-formula-action"><option value="sum">Suma</option><option value="subtract">Resta</option><option value="multiply">Multiplicación</option><option value="divide">División</option><option value="average">Promedio</option><option value="prorate">Prorrateo</option><option value="progress">Avance</option></select><label>Columnas</label><div class="formula-columns">${available.map(item=>`<label><input type="checkbox" value="${item.id}" ${(column.formulaColumns||[]).includes(item.id)?"checked":""}><span>${escapeHTML(item.name)}</span></label>`).join("")||'<div class="formula-hint">Primero crea columnas numéricas.</div>'}</div><label>Resultado</label><select class="talent-formula-result"><option value="currency">Moneda</option><option value="number">Número</option><option value="percent">Porcentaje</option></select><button class="config-save">Guardar fórmula</button></div>`;submenu.querySelector(".talent-formula-action").value=column.formulaAction||"sum";submenu.querySelector(".talent-formula-result").value=column.formulaResultType||"currency";submenu.querySelector(".config-save").addEventListener("click",()=>{column.formulaAction=submenu.querySelector(".talent-formula-action").value;column.formulaResultType=submenu.querySelector(".talent-formula-result").value;column.formulaColumns=[...submenu.querySelectorAll(".formula-columns input:checked")].map(input=>input.value);save();renderTable();submenu.classList.remove("open")})}positionTypeConfig(submenu,trigger)}
function openTools(kind,trigger){const company=activeCompany();const menu=document.getElementById("talentToolsMenu");if(!company||!menu)return;const options=company.columns.map(column=>`<option value="${column.id}">${escapeHTML(column.name)}</option>`).join("");if(kind==="search")menu.innerHTML=`<div class="tools-menu-title">Buscar en Nómina</div><input class="tools-menu-input" type="search" placeholder="Buscar empleado o dato…" value="${escapeHTML(viewState.search)}"><button class="tools-menu-clear">Limpiar búsqueda</button>`;if(kind==="filter")menu.innerHTML=`<div class="tools-menu-title">Filtrar registros</div><select class="tools-menu-select"><option value="">Selecciona una columna</option>${options}</select><input class="tools-menu-input" placeholder="Contiene…" value="${escapeHTML(viewState.filterValue)}"><button class="tools-menu-clear">Limpiar filtro</button>`;if(kind==="sort")menu.innerHTML=`<div class="tools-menu-title">Ordenar registros</div><select class="tools-menu-select"><option value="">Sin ordenar</option>${options}</select><select class="tools-menu-select"><option value="asc">Ascendente</option><option value="desc">Descendente</option></select>`;if(kind==="settings")menu.innerHTML=`<div class="tools-menu-title">Ajustes de Nómina</div><button class="talent-menu-action" data-action="rename-company"><svg><use href="#i-edit"></use></svg><span>Renombrar empresa</span></button><button class="talent-menu-action" data-action="add-column"><svg><use href="#i-plus"></use></svg><span>Agregar columna</span></button>`;const rect=trigger.getBoundingClientRect();menu.style.left=Math.min(rect.left,window.innerWidth-268)+"px";menu.style.top=Math.min(rect.bottom+5,window.innerHeight-230)+"px";menu.classList.add("open");const inputs=menu.querySelectorAll("input");const selects=menu.querySelectorAll("select");if(kind==="search")inputs[0].addEventListener("input",()=>{viewState.search=inputs[0].value;renderTable()});if(kind==="filter"){selects[0].value=viewState.filterColumn;selects[0].addEventListener("change",()=>{viewState.filterColumn=selects[0].value;renderTable()});inputs[0].addEventListener("input",()=>{viewState.filterValue=inputs[0].value;renderTable()})}if(kind==="sort"){selects[0].value=viewState.sortColumn;selects[1].value=viewState.sortDirection;selects.forEach(select=>select.addEventListener("change",()=>{viewState.sortColumn=selects[0].value;viewState.sortDirection=selects[1].value;renderTable()}))}menu.querySelector(".tools-menu-clear")?.addEventListener("click",()=>{if(kind==="search")viewState.search="";else{viewState.filterColumn="";viewState.filterValue=""}menu.classList.remove("open");renderTable()});menu.querySelector('[data-action="rename-company"]')?.addEventListener("click",()=>renameCompany(activeCompany()));menu.querySelector('[data-action="add-column"]')?.addEventListener("click",()=>{menu.classList.remove("open");addColumn()})}
function renameCompany(company){const name=prompt("Nombre de la pestaña:",company?.name||"");if(name?.trim()&&company){company.name=name.trim();save();renderHumanTalent()}}
function resizeColumn(event,column){event.preventDefault();event.stopPropagation();const start=event.clientX;const startWidth=Number(column.width)||150;document.body.classList.add("column-resizing");const move=pointer=>{column.width=Math.max(70,Math.min(600,startWidth+pointer.clientX-start));document.querySelectorAll(`[data-talent-column-id="${column.id}"]`).forEach(cell=>{cell.style.width=column.width+"px";cell.style.minWidth=column.width+"px";cell.style.maxWidth=column.width+"px"})};const up=()=>{document.body.classList.remove("column-resizing");document.removeEventListener("pointermove",move);save();renderTable()};document.addEventListener("pointermove",move);document.addEventListener("pointerup",up,{once:true})}
function openColumnMenu(trigger,column){const company=activeCompany();const menu=document.getElementById("talentColumnMenu");const index=company?.columns.findIndex(item=>item.id===column.id)??-1;if(!company||!menu||index<0)return;menu.innerHTML=`<button data-column-action="move"><svg><use href="#i-move"></use></svg><span>Mover</span></button><button data-column-action="fix"><svg><use href="#i-pin"></use></svg><span>Fijar hasta esta columna</span></button><button data-column-action="delete" class="danger"><svg><use href="#i-trash"></use></svg><span>Eliminar</span></button>`;const rect=trigger.getBoundingClientRect();menu.style.left=Math.min(rect.left,window.innerWidth-233)+"px";menu.style.top=Math.min(rect.bottom+5,window.innerHeight-118)+"px";menu.classList.add("open");menu.querySelector('[data-column-action="move"]').addEventListener("click",()=>{movingColumns=true;menu.classList.remove("open");renderTable()});menu.querySelector('[data-column-action="fix"]').addEventListener("click",()=>{company.columns.forEach((item,itemIndex)=>item.fixed=itemIndex<=index);menu.classList.remove("open");save();renderTable()});menu.querySelector('[data-column-action="delete"]').addEventListener("click",()=>{if(company.columns.length<=1)return;company.columns.splice(index,1);company.rows.forEach(row=>delete row[column.id]);menu.classList.remove("open");save();renderTable()})}
export function initHumanTalent(options={}){
 config=options;state();const mainTabs=document.getElementById("talentMainTabs");
 mainTabs?.addEventListener("click",event=>{if(event.target.closest("[data-add-talent-section]")){const name=prompt("Nombre de la nueva pestaña:","Nueva pestaña");if(name?.trim()){const section=defaultSection(name.trim(),"custom");state().sections.push(section);activeSectionId=section.id;state().activeSectionId=section.id;save();renderHumanTalent()}return}const button=event.target.closest("[data-talent-section]");if(!button)return;activeSectionId=button.dataset.talentSection;state().activeSectionId=activeSectionId;activeCompanyId=null;movingColumns=false;save();renderHumanTalent()});
 mainTabs?.addEventListener("dblclick",event=>{const button=event.target.closest("[data-talent-section]");const section=state().sections.find(item=>item.id===button?.dataset.talentSection);if(!section)return;const name=prompt("Nombre de la pestaña:",section.name);if(name?.trim()){section.name=name.trim();save();renderHumanTalent()}});
 document.getElementById("payrollCompanyTabs")?.addEventListener("click",event=>{if(event.target.closest("[data-add-talent-company]")){const name=prompt("Nombre de la empresa:",`Empresa${activeSection().companies.length+1}`);if(name?.trim()){const company={id:uid(),name:name.trim(),columns:defaultColumns(),rows:[],cleanColumnTypesApplied:true,employeeFormV2Applied:true};activeSection().companies.push(company);activeCompanyId=company.id;activeSection().activeCompanyId=company.id;save();renderHumanTalent()}return}const button=event.target.closest("[data-talent-company]");if(!button)return;activeCompanyId=button.dataset.talentCompany;activeSection().activeCompanyId=activeCompanyId;movingColumns=false;save();renderTable()});
 document.getElementById("payrollCompanyTabs")?.addEventListener("dblclick",event=>{const button=event.target.closest("[data-talent-company]");renameCompany(activeSection().companies.find(item=>item.id===button?.dataset.talentCompany))});
 document.getElementById("talentAddRow")?.addEventListener("click",addRow);document.getElementById("talentAddRowBottom")?.addEventListener("click",addRow);document.getElementById("talentAddColumn")?.addEventListener("click",addColumn);document.querySelectorAll("[data-talent-tool]").forEach(button=>button.addEventListener("click",()=>openTools(button.dataset.talentTool,button)));
 const head=document.getElementById("payrollHead");
 head?.addEventListener("click",event=>{const th=event.target.closest("[data-talent-column]");const company=activeCompany();const column=company?.columns.find(item=>item.id===th?.dataset.talentColumn);if(!column)return;const typeButton=event.target.closest(".talent-type-trigger");if(typeButton){document.dispatchEvent(new CustomEvent("open-shared-type-menu",{detail:{trigger:typeButton,currentType:column.type,onQuickFormat:(style,textColor,cellColor)=>{if(style)column.textStyle=style;if(textColor)column.textColor=textColor;if(cellColor)column.cellColor=cellColor;save();renderTable()},onSelect:(type,options={})=>{const previousType=column.type;column.type=type;if(type==="status"){if(previousType!=="status")column.statusOptions=[];delete column.options}else if(type==="select"||type==="multiselect"){if(previousType!==type)column.options=[];delete column.statusOptions;company.rows.forEach(row=>{if(type==="multiselect"&&!Array.isArray(row[column.id]))row[column.id]=[]})}else if(type==="checkbox"){if(previousType!=="checkbox"){column.checkboxColor="#2383e2";column.checkboxHighlight=false}delete column.statusOptions;delete column.options;company.rows.forEach(row=>row[column.id]=Boolean(row[column.id]))}else if(type==="formula"){if(previousType!=="formula")column.formulaColumns=[];column.formulaAction=options.formulaAction&&options.formulaAction!=="advanced"?options.formulaAction:(column.formulaAction||"sum");column.formulaResultType=["prorate","progress"].includes(column.formulaAction)?"percent":(column.formulaResultType||"currency")}else if(type==="text"){column.textStyle=column.textStyle||"normal"}else if(type==="date"){column.dateFormat=column.dateFormat||"dd/mm/yyyy"}else if(type!=="url"){delete column.statusOptions;delete column.options;delete column.checkboxColor;delete column.checkboxHighlight}save();renderTable();const configurable=["status","select","multiselect","checkbox","text","date","formula"];if(configurable.includes(type))setTimeout(()=>{const refreshedTrigger=document.querySelector(`[data-talent-column="${column.id}"] .talent-type-trigger`);if(!refreshedTrigger)return;if(type==="checkbox")configureCheckboxType(refreshedTrigger,column);else if(["status","select","multiselect"].includes(type))configureChoiceType(refreshedTrigger,column,type);else configureAdvancedType(refreshedTrigger,column,type)},0)}}}));return}const settings=event.target.closest(".talent-column-settings");if(settings){event.stopPropagation();openColumnMenu(settings,column)}});
 head?.addEventListener("change",event=>{const th=event.target.closest("[data-talent-column]");const column=activeCompany()?.columns.find(item=>item.id===th?.dataset.talentColumn);if(column&&event.target.classList.contains("talent-column-name")){column.name=event.target.value.trim()||"Columna";save()}});
 head?.addEventListener("pointerdown",event=>{const th=event.target.closest("[data-talent-column]");const column=activeCompany()?.columns.find(item=>item.id===th?.dataset.talentColumn);if(column&&event.target.closest(".talent-column-resizer"))resizeColumn(event,column)});
 head?.addEventListener("dragstart",event=>{const th=event.target.closest("[data-talent-column]");if(!movingColumns||!th)return;draggedColumnId=th.dataset.talentColumn;event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",draggedColumnId)});head?.addEventListener("dragover",event=>{if(movingColumns)event.preventDefault()});head?.addEventListener("drop",event=>{if(!movingColumns)return;event.preventDefault();const company=activeCompany();const target=event.target.closest("[data-talent-column]");const from=company?.columns.findIndex(item=>item.id===draggedColumnId)??-1;const to=company?.columns.findIndex(item=>item.id===target?.dataset.talentColumn)??-1;if(from>=0&&to>=0&&from!==to){const [column]=company.columns.splice(from,1);company.columns.splice(to,0,column)}movingColumns=false;draggedColumnId=null;save();renderTable()});head?.addEventListener("dragend",()=>{movingColumns=false;draggedColumnId=null;renderTable()});
 const body=document.getElementById("payrollBody");body?.addEventListener("pointerdown",event=>{if(event.target.closest(".talent-fill-handle")){beginTalentFill(event);return}const cell=event.target.closest("td[data-talent-column-id]");if(cell)selectTalentCell(cell)});body?.addEventListener("keydown",event=>{const input=event.target.closest("input[data-talent-cell]");if(event.key!=="Enter"||!input||input.type==="checkbox"||input.type==="date")return;event.preventDefault();input.blur()});body?.addEventListener("focusout",event=>{const cell=event.target.closest("td[data-talent-column-id]");if(cell&&selectedTalentCell)setTimeout(()=>{if(!cell.contains(document.activeElement))paintSelectedTalentCell()},0)});body?.addEventListener("change",event=>{const input=event.target.closest("[data-talent-cell]");const company=activeCompany();const row=company?.rows.find(item=>item.id===event.target.closest("[data-talent-row]")?.dataset.talentRow);if(!input||!row)return;const column=company.columns.find(item=>item.id===input.dataset.talentCell);row[input.dataset.talentCell]=input.type==="checkbox"?input.checked:column?.type==="date"?normalizeDateValue(input.value):["currency","subtotal","total","percent","number"].includes(column?.type)?numeric(input.value):input.value;save();renderTable()});body?.addEventListener("click",event=>{const company=activeCompany();const row=company?.rows.find(item=>item.id===event.target.closest("[data-talent-row]")?.dataset.talentRow);const choice=event.target.closest("[data-talent-choice]");if(choice&&row){const column=company.columns.find(item=>item.id===choice.dataset.talentChoice);if(column)openChoice(choice,row,column,choice.dataset.choiceKind);return}if(event.target.closest(".delete-talent-row")&&row){company.rows=company.rows.filter(item=>item.id!==row.id);save();renderTable()}});
 body?.addEventListener("click",event=>{const open=event.target.closest(".talent-employee-open");if(open){event.stopPropagation();openEmployeeForm(open.dataset.employeeId);reorderEmployeeForm();enhanceEmployeeFormSelections()}});
 document.getElementById("closeTalentEmployeePanel")?.addEventListener("click",closeEmployeePanel);document.getElementById("talentEmployeeOverlay")?.addEventListener("click",closeEmployeePanel);
 document.addEventListener("workspace:viewchange",event=>{if(event.detail.view==="talent")renderHumanTalent()});document.addEventListener("click",event=>{const tools=document.getElementById("talentToolsMenu");const columnMenu=document.getElementById("talentColumnMenu");if(tools&&!tools.contains(event.target)&&!event.target.closest("[data-talent-tool]"))tools.classList.remove("open");if(columnMenu&&!columnMenu.contains(event.target)&&!event.target.closest(".talent-column-settings"))columnMenu.classList.remove("open");const choice=document.querySelector(".talent-choice-menu");if(choice&&!choice.contains(event.target)&&!event.target.closest("[data-talent-choice]")&&!event.target.closest(".talent-form-select"))choice.remove();if(!event.target.closest(".talent-table")&&!event.target.closest(".talent-choice-menu")&&!event.target.closest("#typeMenu")&&!event.target.closest("#typeSubmenu"))clearTalentCellSelection()});renderHumanTalent()
}





